1	/**
2	 * Tests for Expenses Page - Filter and Analytics Features
3	 *
4	 * Specification Coverage:
5	 * - #{#exp6a} Uncategorized Expenses Queue View
6	 * - #{#exp7a} Category Filter and Analytics
7	 * - #{#edf1a} Expenses View URL Date Filter Integration
8	 * - #{#edf4a} URL Parameter Validation
9	 *
10	 * Authority: developer
11	 * Priority: Medium (#{#exp6a}), Medium (#{#exp7a}), High (#{#edf1a}), Medium (#{#edf4a})
12	 *
13	 * Note: These are unit/integration tests for page logic.
14	 * Full UI e2e tests will be covered by Playwright tests.
15	 */
16	
17	import { describe, it, expect } from 'vitest';
18	import type { Expense } from '$lib/services/ExpenseService';
19	import { getValidDate } from '$lib/utils/dateValidation';
20	import { makeExpense } from './builders/rowBuilders';
21	
22	/**
23	 * Mock expense data for testing
24	 */
25	const mockExpenses: Expense[] = [
26		makeExpense({
27			receipt_id: 'rec-1',
28			merchant_name: 'Safeway',
29			total_amount: 123.45,
30			transaction_date: '2025-12-05',
31			receipt_image_path: 'path/to/receipt1.jpg',
32			category_id: 'cat-groceries',
33			category_name: 'Groceries',
34			category_color: '#10B981',
35			categorization_source: 'manual'
36		}),
37		makeExpense({
38			receipt_id: 'rec-2',
39			merchant_name: 'Shell Gas',
40			total_amount: 45.67,
41			transaction_date: '2025-12-04',
42			receipt_image_path: 'path/to/receipt2.jpg',
43			category_id: 'cat-transport',
44			category_name: 'Transportation',
45			category_color: '#3B82F6',
46			categorization_source: 'auto'
47		}),
48		makeExpense({
49			receipt_id: 'rec-3',
50			merchant_name: 'Amazon',
51			total_amount: 89.12,
52			transaction_date: '2025-12-03',
53			receipt_image_path: 'path/to/receipt3.jpg'
54		}),
55		makeExpense({
56			receipt_id: 'rec-4',
57			merchant_name: 'Best Buy',
58			total_amount: 299.99,
59			transaction_date: '2025-12-02',
60			receipt_image_path: 'path/to/receipt4.jpg'
61		}),
62		makeExpense({
63			receipt_id: 'rec-5',
64			merchant_name: 'Costco',
65			total_amount: 156.78,
66			transaction_date: '2025-12-01',
67			receipt_image_path: 'path/to/receipt5.jpg',
68			category_id: 'cat-groceries',
69			category_name: 'Groceries',
70			category_color: '#10B981',
71			categorization_source: 'manual'
72		})
73	];
74	
75	describe('#{#exp6a} Uncategorized Expenses Queue View', () => {
76		describe('Filter Logic', () => {
77			/**
78			 * #{#exp6a} Criterion 2: Filter must display only expenses with category_id = NULL
79			 */
80			function filterUncategorizedExpenses(expenses: Expense[]): Expense[] {
81				return expenses.filter((expense) => expense.category_id === null);
82			}
83	
84			it('should filter to show only uncategorized expenses', () => {
85				const filtered = filterUncategorizedExpenses(mockExpenses);
86	
87				expect(filtered.length).toBe(2);
88				expect(filtered.every((e) => e.category_id === null)).toBe(true);
89				expect(filtered[0].merchant_name).toBe('Amazon');
90				expect(filtered[1].merchant_name).toBe('Best Buy');
91			});
92	
93			it('should return empty array when all expenses are categorized', () => {
94				const categorizedExpenses = mockExpenses.filter((e) => e.category_id !== null);
95				const filtered = filterUncategorizedExpenses(categorizedExpenses);
96	
97				expect(filtered.length).toBe(0);
98			});
99	
100			it('should return all expenses when none are categorized', () => {
101				const uncategorizedExpenses = mockExpenses.map((e) => ({
102					...e,
103					category_id: null,
104					category_name: null,
105					category_color: null
106				}));
107				const filtered = filterUncategorizedExpenses(uncategorizedExpenses);
108	
109				expect(filtered.length).toBe(mockExpenses.length);
110			});
111		});
112	
113		describe('Count Calculation', () => {
114			/**
115			 * #{#exp6a} Criterion 3: Filter must show count "X uncategorized expenses"
116			 */
117			function getUncategorizedCount(expenses: Expense[]): number {
118				return expenses.filter((e) => e.category_id === null).length;
119			}
120	
121			it('should count uncategorized expenses correctly', () => {
122				const count = getUncategorizedCount(mockExpenses);
123				expect(count).toBe(2);
124			});
125	
126			it('should return 0 when all expenses are categorized', () => {
127				const categorizedExpenses = mockExpenses.filter((e) => e.category_id !== null);
128				const count = getUncategorizedCount(categorizedExpenses);
129				expect(count).toBe(0);
130			});
131	
132			it('should return total count when all expenses are uncategorized', () => {
133				const uncategorizedExpenses = mockExpenses.map((e) => ({
134					...e,
135					category_id: null
136				}));
137				const count = getUncategorizedCount(uncategorizedExpenses);
138				expect(count).toBe(mockExpenses.length);
139			});
140		});
141	
142		describe('Sorting by Date', () => {
143			/**
144			 * #{#exp6a} Criterion 4: Uncategorized expenses sorted by date (newest first)
145			 */
146			function sortByDateDesc(expenses: Expense[]): Expense[] {
147				return [...expenses].sort(
148					(a, b) => new Date(b.transaction_date).getTime() - new Date(a.transaction_date).getTime()
149				);
150			}
151	
152			it('should sort uncategorized expenses by date (newest first)', () => {
153				const uncategorized = mockExpenses.filter((e) => e.category_id === null);
154				const sorted = sortByDateDesc(uncategorized);
155	
156				expect(sorted.length).toBe(2);
157				expect(sorted[0].transaction_date).toBe('2025-12-03'); // Amazon (newer)
158				expect(sorted[1].transaction_date).toBe('2025-12-02'); // Best Buy (older)
159			});
160	
161			it('should handle single uncategorized expense', () => {
162				const singleExpense = [mockExpenses[2]]; // Amazon
163				const sorted = sortByDateDesc(singleExpense);
164	
165				expect(sorted.length).toBe(1);
166				expect(sorted[0].merchant_name).toBe('Amazon');
167			});
168	
169			it('should handle empty array', () => {
170				const sorted = sortByDateDesc([]);
171				expect(sorted.length).toBe(0);
172			});
173	
174			it('should sort all expenses by date descending', () => {
175				const sorted = sortByDateDesc(mockExpenses);
176	
177				// Verify descending order
178				for (let i = 0; i < sorted.length - 1; i++) {
179					const current = new Date(sorted[i].transaction_date).getTime();
180					const next = new Date(sorted[i + 1].transaction_date).getTime();
181					expect(current).toBeGreaterThanOrEqual(next);
182				}
183			});
184		});
185	
186		describe('URL Parameter Handling', () => {
187			/**
188			 * #{#exp6a} Criterion 7: Filter state persists in URL (?filter=uncategorized)
189			 */
190			function parseFilterFromURL(url: string): string | null {
191				const params = new URLSearchParams(url.split('?')[1] || '');
192				return params.get('filter');
193			}
194	
195			function createFilterURL(filter: string | null): string {
196				if (!filter) return '/expenses';
197				return `/expenses?filter=${encodeURIComponent(filter)}`;
198			}
199	
200			it('should parse "uncategorized" filter from URL', () => {
201				const url = '/expenses?filter=uncategorized';
202				const filter = parseFilterFromURL(url);
203				expect(filter).toBe('uncategorized');
204			});
205	
206			it('should return null when no filter in URL', () => {
207				const url = '/expenses';
208				const filter = parseFilterFromURL(url);
209				expect(filter).toBeNull();
210			});
211	
212			it('should create URL with uncategorized filter', () => {
213				const url = createFilterURL('uncategorized');
214				expect(url).toBe('/expenses?filter=uncategorized');
215			});
216	
217			it('should create URL without filter when filter is null', () => {
218				const url = createFilterURL(null);
219				expect(url).toBe('/expenses');
220			});
221	
222			it('should handle URL with other query parameters', () => {
223				const url = '/expenses?startDate=2025-01-01&filter=uncategorized&endDate=2025-12-31';
224				const filter = parseFilterFromURL(url);
225				expect(filter).toBe('uncategorized');
226			});
227		});
228	});
229	
230	describe('#{#exp7a} Category Filter and Analytics', () => {
231		describe('Category Filter Logic', () => {
232			/**
233			 * #{#exp7a} Criterion 2: Show only expenses in selected category
234			 */
235			function filterByCategory(expenses: Expense[], categoryId: string | null): Expense[] {
236				if (!categoryId) return expenses;
237				return expenses.filter((e) => e.category_id === categoryId);
238			}
239	
240			/**
241			 * #{#exp7a} Criterion 4: Multiple categories selectable (OR logic)
242			 */
243			function filterByCategories(expenses: Expense[], categoryIds: string[]): Expense[] {
244				if (categoryIds.length === 0) return expenses;
245				return expenses.filter((e) => e.category_id && categoryIds.includes(e.category_id));
246			}
247	
248			it('should filter expenses by single category', () => {
249				const filtered = filterByCategory(mockExpenses, 'cat-groceries');
250	
251				expect(filtered.length).toBe(2);
252				expect(filtered.every((e) => e.category_id === 'cat-groceries')).toBe(true);
253			});
254	
255			it('should return all expenses when category is null', () => {
256				const filtered = filterByCategory(mockExpenses, null);
257				expect(filtered.length).toBe(mockExpenses.length);
258			});
259	
260			it('should return empty array when no expenses match category', () => {
261				const filtered = filterByCategory(mockExpenses, 'cat-nonexistent');
262				expect(filtered.length).toBe(0);
263			});
264	
265			it('should filter by multiple categories with OR logic', () => {
266				const filtered = filterByCategories(mockExpenses, ['cat-groceries', 'cat-transport']);
267	
268				expect(filtered.length).toBe(3);
269				expect(filtered.some((e) => e.category_id === 'cat-groceries')).toBe(true);
270				expect(filtered.some((e) => e.category_id === 'cat-transport')).toBe(true);
271			});
272	
273			it('should return all expenses when category list is empty', () => {
274				const filtered = filterByCategories(mockExpenses, []);
275				expect(filtered.length).toBe(mockExpenses.length);
276			});
277	
278			it('should exclude uncategorized expenses from category filter', () => {
279				const filtered = filterByCategories(mockExpenses, ['cat-groceries']);
280	
281				expect(filtered.every((e) => e.category_id !== null)).toBe(true);
282			});
283		});
284	
285		describe('Expense Count per Category', () => {
286			/**
287			 * #{#exp7a} Criterion 3: Show count like "Groceries (24)"
288			 */
289			function getExpenseCountByCategory(expenses: Expense[]): Record<string, number> {
290				const counts: Record<string, number> = {};
291	
292				expenses.forEach((expense) => {
293					const key = expense.category_id || 'uncategorized';
294					counts[key] = (counts[key] || 0) + 1;
295				});
296	
297				return counts;
298			}
299	
300			it('should count expenses per category', () => {
301				const counts = getExpenseCountByCategory(mockExpenses);
302	
303				expect(counts['cat-groceries']).toBe(2);
304				expect(counts['cat-transport']).toBe(1);
305				expect(counts['uncategorized']).toBe(2);
306			});
307	
308			it('should handle all expenses in one category', () => {
309				const sameCategory = mockExpenses.map((e) => ({
310					...e,
311					category_id: 'cat-groceries'
312				}));
313				const counts = getExpenseCountByCategory(sameCategory);
314	
315				expect(counts['cat-groceries']).toBe(mockExpenses.length);
316			});
317	
318			it('should handle all uncategorized expenses', () => {
319				const uncategorized = mockExpenses.map((e) => ({
320					...e,
321					category_id: null
322				}));
323				const counts = getExpenseCountByCategory(uncategorized);
324	
325				expect(counts['uncategorized']).toBe(mockExpenses.length);
326			});
327		});
328	
329		describe('Spending Summary Calculations', () => {
330			/**
331			 * #{#exp7a} Criterion 6: Summary panel shows total spending per category
332			 */
333			interface CategorySpending {
334				categoryId: string;
335				categoryName: string;
336				totalAmount: number;
337				expenseCount: number;
338			}
339	
340			function calculateSpendingSummary(expenses: Expense[]): CategorySpending[] {
341				const summaryMap = new Map<string, CategorySpending>();
342	
343				expenses.forEach((expense) => {
344					const catId = expense.category_id || 'uncategorized';
345					const catName = expense.category_name || 'Uncategorized';
346	
347					if (!summaryMap.has(catId)) {
348						summaryMap.set(catId, {
349							categoryId: catId,
350							categoryName: catName,
351							totalAmount: 0,
352							expenseCount: 0
353						});
354					}
355	
356					const summary = summaryMap.get(catId)!;
357					summary.totalAmount += expense.total_amount ?? 0;
358					summary.expenseCount += 1;
359				});
360	
361				return Array.from(summaryMap.values());
362			}
363	
364			function calculateGrandTotal(expenses: Expense[]): number {
365				return expenses.reduce((sum, expense) => sum + (expense.total_amount ?? 0), 0);
366			}
367	
368			it('should calculate spending summary by category', () => {
369				const summary = calculateSpendingSummary(mockExpenses);
370	
371				const groceries = summary.find((s) => s.categoryId === 'cat-groceries');
372				expect(groceries).toBeDefined();
373				expect(groceries!.totalAmount).toBeCloseTo(123.45 + 156.78, 2);
374				expect(groceries!.expenseCount).toBe(2);
375			});
376	
377			it('should include uncategorized in summary', () => {
378				const summary = calculateSpendingSummary(mockExpenses);
379	
380				const uncategorized = summary.find((s) => s.categoryId === 'uncategorized');
381				expect(uncategorized).toBeDefined();
382				expect(uncategorized!.totalAmount).toBeCloseTo(89.12 + 299.99, 2);
383				expect(uncategorized!.expenseCount).toBe(2);
384			});
385	
386			it('should calculate grand total correctly', () => {
387				const total = calculateGrandTotal(mockExpenses);
388	
389				const expected = 123.45 + 45.67 + 89.12 + 299.99 + 156.78;
390				expect(total).toBeCloseTo(expected, 2);
391			});
392	
393			it('should handle empty expense list', () => {
394				const summary = calculateSpendingSummary([]);
395				expect(summary.length).toBe(0);
396	
397				const total = calculateGrandTotal([]);
398				expect(total).toBe(0);
399			});
400	
401			it('should sort summary by total amount descending', () => {
402				const summary = calculateSpendingSummary(mockExpenses);
403				const sorted = [...summary].sort((a, b) => b.totalAmount - a.totalAmount);
404	
405				// Verify descending order
406				for (let i = 0; i < sorted.length - 1; i++) {
407					expect(sorted[i].totalAmount).toBeGreaterThanOrEqual(sorted[i + 1].totalAmount);
408				}
409			});
410		});
411	
412		describe('Combined Filters (Category + Date Range)', () => {
413			/**
414			 * #{#exp7a} Criterion 5: Filter must work with date range filter
415			 */
416			function filterByDateRange(
417				expenses: Expense[],
418				startDate: string | null,
419				endDate: string | null
420			): Expense[] {
421				let filtered = expenses;
422	
423				if (startDate) {
424					const start = new Date(startDate).getTime();
425					filtered = filtered.filter((e) => new Date(e.transaction_date).getTime() >= start);
426				}
427	
428				if (endDate) {
429					const end = new Date(endDate).getTime();
430					filtered = filtered.filter((e) => new Date(e.transaction_date).getTime() <= end);
431				}
432	
433				return filtered;
434			}
435	
436			function applyCombinedFilters(
437				expenses: Expense[],
438				categoryId: string | null,
439				startDate: string | null,
440				endDate: string | null
441			): Expense[] {
442				let filtered = expenses;
443	
444				// Apply category filter
445				if (categoryId) {
446					filtered = filtered.filter((e) => e.category_id === categoryId);
447				}
448	
449				// Apply date range filter
450				filtered = filterByDateRange(filtered, startDate, endDate);
451	
452				return filtered;
453			}
454	
455			it('should filter by date range', () => {
456				const filtered = filterByDateRange(mockExpenses, '2025-12-03', '2025-12-05');
457	
458				expect(filtered.length).toBe(3); // Dec 3, 4, 5
459				expect(
460					filtered.every((e) => {
461						const date = new Date(e.transaction_date).getTime();
462						return (
463							date >= new Date('2025-12-03').getTime() && date <= new Date('2025-12-05').getTime()
464						);
465					})
466				).toBe(true);
467			});
468	
469			it('should filter by start date only', () => {
470				const filtered = filterByDateRange(mockExpenses, '2025-12-03', null);
471	
472				expect(filtered.length).toBe(3); // Dec 3, 4, 5
473			});
474	
475			it('should filter by end date only', () => {
476				const filtered = filterByDateRange(mockExpenses, null, '2025-12-03');
477	
478				expect(filtered.length).toBe(3); // Dec 1, 2, 3
479			});
480	
481			it('should combine category and date filters', () => {
482				const filtered = applyCombinedFilters(
483					mockExpenses,
484					'cat-groceries',
485					'2025-12-04',
486					'2025-12-06'
487				);
488	
489				expect(filtered.length).toBe(1); // Only Safeway on Dec 5
490				expect(filtered[0].merchant_name).toBe('Safeway');
491			});
492	
493			it('should return empty when filters have no matches', () => {
494				const filtered = applyCombinedFilters(
495					mockExpenses,
496					'cat-groceries',
497					'2030-01-01',
498					'2030-12-31'
499				);
500	
501				expect(filtered.length).toBe(0);
502			});
503	
504			it('should update summary based on combined filters', () => {
505				const filtered = applyCombinedFilters(
506					mockExpenses,
507					'cat-groceries',
508					'2025-12-01',
509					'2025-12-05'
510				);
511	
512				const summary = filtered.reduce((sum, e) => sum + (e.total_amount ?? 0), 0);
513				expect(summary).toBeCloseTo(123.45 + 156.78, 2);
514			});
515		});
516	
517		describe('URL Parameter Handling for Category Filter', () => {
518			/**
519			 * #{#exp7a} Category filter should persist in URL
520			 */
521			function parseCategoryFromURL(url: string): string | null {
522				const params = new URLSearchParams(url.split('?')[1] || '');
523				return params.get('category');
524			}
525	
526			function parseMultipleCategoriesFromURL(url: string): string[] {
527				const params = new URLSearchParams(url.split('?')[1] || '');
528				const category = params.get('category');
529				return category ? category.split(',') : [];
530			}
531	
532			function createCategoryFilterURL(categories: string[]): string {
533				if (categories.length === 0) return '/expenses';
534				return `/expenses?category=${categories.join(',')}`;
535			}
536	
537			it('should parse single category from URL', () => {
538				const url = '/expenses?category=cat-groceries';
539				const category = parseCategoryFromURL(url);
540				expect(category).toBe('cat-groceries');
541			});
542	
543			it('should parse multiple categories from URL', () => {
544				const url = '/expenses?category=cat-groceries,cat-transport';
545				const categories = parseMultipleCategoriesFromURL(url);
546				expect(categories).toEqual(['cat-groceries', 'cat-transport']);
547			});
548	
549			it('should create URL with single category', () => {
550				const url = createCategoryFilterURL(['cat-groceries']);
551				expect(url).toBe('/expenses?category=cat-groceries');
552			});
553	
554			it('should create URL with multiple categories', () => {
555				const url = createCategoryFilterURL(['cat-groceries', 'cat-transport']);
556				expect(url).toBe('/expenses?category=cat-groceries,cat-transport');
557			});
558	
559			it('should create URL without category when array is empty', () => {
560				const url = createCategoryFilterURL([]);
561				expect(url).toBe('/expenses');
562			});
563		});
564	});
565	
566	describe('Integration: Combined Filters and Analytics', () => {
567		/**
568		 * Test complex scenarios with multiple filters active
569		 */
570		function applyAllFilters(
571			expenses: Expense[],
572			options: {
573				showUncategorizedOnly?: boolean;
574				categoryIds?: string[];
575				startDate?: string | null;
576				endDate?: string | null;
577			}
578		): Expense[] {
579			let filtered = expenses;
580	
581			// Uncategorized filter takes precedence
582			if (options.showUncategorizedOnly) {
583				filtered = filtered.filter((e) => e.category_id === null);
584			} else if (options.categoryIds && options.categoryIds.length > 0) {
585				filtered = filtered.filter(
586					(e) => e.category_id && options.categoryIds!.includes(e.category_id)
587				);
588			}
589	
590			// Apply date filters
591			if (options.startDate) {
592				const start = new Date(options.startDate).getTime();
593				filtered = filtered.filter((e) => new Date(e.transaction_date).getTime() >= start);
594			}
595	
596			if (options.endDate) {
597				const end = new Date(options.endDate).getTime();
598				filtered = filtered.filter((e) => new Date(e.transaction_date).getTime() <= end);
599			}
600	
601			return filtered;
602		}
603	
604		it('should handle uncategorized filter + date range', () => {
605			const filtered = applyAllFilters(mockExpenses, {
606				showUncategorizedOnly: true,
607				startDate: '2025-12-02',
608				endDate: '2025-12-04'
609			});
610	
611			// Should show Amazon (Dec 3) and Best Buy (Dec 2), both uncategorized
612			expect(filtered.length).toBe(2);
613			expect(filtered.every((e) => e.category_id === null)).toBe(true);
614		});
615	
616		it('should ignore category filter when uncategorized is active', () => {
617			const filtered = applyAllFilters(mockExpenses, {
618				showUncategorizedOnly: true,
619				categoryIds: ['cat-groceries']
620			});
621	
622			// Uncategorized takes precedence, should show 2 uncategorized
623			expect(filtered.length).toBe(2);
624			expect(filtered.every((e) => e.category_id === null)).toBe(true);
625		});
